def choose_move(observation):
    w = observation['grid_width']
    h = observation['grid_height']
    agents = observation['agents']
    my_id = observation['agent_id']
    pos = agents[my_id]['position']
    ox, oy = pos

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > ox:
            dx = 1
        elif target_x < ox:
            dx = -1
        elif target_y > oy:
            dy = 1
        elif target_y < oy:
            dy = -1
        return [dx, dy]

    def is_valid(nx, ny):
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in observation['obstacles']:
            return True
        return False

    # Find closest resource
    resource_positions = [res['position'] for res in observation.get('resources', [])]
    if resource_positions:
        target = min(resource_positions, key=lambda r: abs(r[0]-ox)+abs(r[1]-oy))
        dx, dy = move_towards(target[0], target[1])
        nx, ny = ox + dx, oy + dy
        if is_valid(nx, ny):
            return [dx, dy]

    # Default: stay if no resource or blocked
    for dx, dy in [[0,1],[1,0],[0,-1],[-1,0]]:
        nx, ny = ox + dx, oy + dy
        if is_valid(nx, ny):
            return [dx, dy]
    return [0, 0]
